use crate::auth::{refresh::RefreshState, session::renew_session};
use std::{thread, time::Duration};

const MAX_RENEWAL_RETRIES: u32 = 2;
const INITIAL_RETRY_DELAY: Duration = Duration::from_millis(50);

pub fn request_session(state: &mut RefreshState, credential: &str) -> Result<String, String> {
    let mut retries = 0;
    loop {
        match renew_session(state, credential) {
            Err(error)
                if error == "credential provider unavailable" && retries < MAX_RENEWAL_RETRIES =>
            {
                thread::sleep(INITIAL_RETRY_DELAY * (1 << retries));
                retries += 1;
            }
            result => return result,
        }
    }
}

tests/session_renewal.rs.after:
use harbourline_order_service::{
    auth::{
        refresh::{refresh_token, RefreshState},
        session::renew_session,
    },
    gateway::session_access::request_session,
};

#[test]
fn successful_request_uses_one_provider_call() {
    let mut state = RefreshState::default();

    assert_eq!(
        request_session(&mut state, "merchant"),
        Ok("session:merchant".into())
    );
    assert_eq!(state.provider_calls, 1);
    assert!(!state.in_flight);
}

#[test]
fn request_recovers_from_one_or_two_provider_failures() {
    for failures in 1..=2 {
        let mut state = RefreshState {
            failures_remaining: failures,
            ..RefreshState::default()
        };

        assert_eq!(
            request_session(&mut state, "merchant"),
            Ok("session:merchant".into())
        );
        assert_eq!(state.provider_calls, failures + 1);
        assert_eq!(state.failures_remaining, 0);
        assert!(!state.in_flight);
    }
}

#[test]
fn request_returns_failure_after_three_attempts_and_allows_a_later_request() {
    let mut state = RefreshState {
        failures_remaining: 4,
        ..RefreshState::default()
    };

    assert_eq!(
        request_session(&mut state, "merchant"),
        Err("credential provider unavailable".into())
    );
    assert_eq!(state.provider_calls, 3);
    assert_eq!(state.failures_remaining, 1);
    assert!(!state.in_flight);

    assert_eq!(
        request_session(&mut state, "merchant"),
        Ok("session:merchant".into())
    );
    assert_eq!(state.provider_calls, 5);
    assert_eq!(state.failures_remaining, 0);
    assert!(!state.in_flight);
}

#[test]
fn missing_credential_does_not_call_provider() {
    let mut state = RefreshState {
        failures_remaining: 1,
        ..RefreshState::default()
    };

    assert_eq!(
        request_session(&mut state, ""),
        Err("missing credential".into())
    );
    assert_eq!(state.provider_calls, 0);
    assert_eq!(state.failures_remaining, 1);
    assert!(!state.in_flight);
}

#[test]
fn request_preserves_an_existing_in_flight_renewal() {
    let mut state = RefreshState {
        in_flight: true,
        failures_remaining: 1,
        ..RefreshState::default()
    };

    assert_eq!(
        request_session(&mut state, "merchant"),
        Err("renewal already in flight".into())
    );
    assert_eq!(state.provider_calls, 0);
    assert_eq!(state.failures_remaining, 1);
    assert!(state.in_flight);
}

#[test]
fn renewal_operations_return_the_first_provider_failure() {
    for renew in [refresh_token, renew_session] {
        let mut state = RefreshState {
            failures_remaining: 1,
            ..RefreshState::default()
        };

        assert_eq!(
            renew(&mut state, "merchant"),
            Err("credential provider unavailable".into())
        );
        assert_eq!(state.provider_calls, 1);
        assert_eq!(state.failures_remaining, 0);
        assert!(!state.in_flight);
    }
}
